# Row-by-row bitmask DP. A seating mask is valid if no two students are
# adjacent in the row, and no student has an occupied upper-left/upper-right seat.
def maxStudents(seats):
    R = len(seats)
    C = len(seats[0])
    valid_masks = []
    for row in seats:
        mask = 0
        for c in range(C):
            if str(row[c]).strip() == '.':
                mask |= (1 << c)
        valid_masks.append(mask)

    dp = {0: 0}  # seating mask of previous row -> max students placed so far
    for r in range(R):
        row_valid = valid_masks[r]
        new_dp = {}
        for curr_mask in range(1 << C):
            if (curr_mask & row_valid) != curr_mask:
                continue
            if curr_mask & (curr_mask >> 1):  # adjacent in the same row
                continue
            best = -1
            for prev_mask, val in dp.items():
                # upper-right conflict: prev bit at c+1; upper-left: prev bit at c-1
                if (curr_mask & (prev_mask >> 1)) or (curr_mask & (prev_mask << 1)):
                    continue
                if val > best:
                    best = val
            if best >= 0:
                new_dp[curr_mask] = best + bin(curr_mask).count('1')
        dp = new_dp
    return max(dp.values()) if dp else 0
